(function(){
  const cx = W()/2, cy = H()/2;
  const minSide = Math.min(W(), H());
  const petalLayers = [
    {ox: -W()*0.4, oy: -H()*0.38, count:7, size:0.9, speed:0.00004, rot:0},
    {ox: W()*0.42, oy: H()*0.4, count:9, size:1.1, speed:-0.00003, rot:Math.PI/9}
  ];

  function hexAlpha(hex, a){
    const r = parseInt(hex.slice(1,3),16);
    const g = parseInt(hex.slice(3,5),16);
    const b = parseInt(hex.slice(5,7),16);
    return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
  }

  function drawPetalLayer(layer, t){
    const px = cx + layer.ox, py = cy + layer.oy;
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(t*layer.speed + layer.rot);
    for(let i=0;i<layer.count;i++){
      const a = (Math.PI*2/layer.count)*i;
      ctx.save();
      ctx.rotate(a);
      const len = 62*layer.size, wid = 24*layer.size;
      const grad = ctx.createLinearGradient(0,0,len,0);
      grad.addColorStop(0, hexAlpha(PALETTE[1], 0.02));
      grad.addColorStop(0.55, hexAlpha(PALETTE[0], 0.2));
      grad.addColorStop(1, hexAlpha(PALETTE[2], 0.06));
      ctx.beginPath();
      ctx.moveTo(0,0);
      ctx.bezierCurveTo(len*0.3, -wid, len*0.8, -wid*0.5, len, 0);
      ctx.bezierCurveTo(len*0.8, wid*0.5, len*0.3, wid, 0, 0);
      ctx.closePath();
      ctx.fillStyle = grad;
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  }

  const particles = [];
  const N = 120;
  for(let i=0;i<N;i++){
    const orbitR = minSide*0.18 + Math.random()*minSide*0.28;
    particles.push({
      angle: Math.random()*Math.PI*2,
      speed: (0.0005 + Math.random()*0.0015) * (Math.random()<0.5?1:-1),
      orbitR: orbitR,
      wob: 4 + Math.random()*8,
      wobSpeed: 0.003 + Math.random()*0.01,
      size: 0.8 + Math.random()*1.8,
      color: PALETTE[Math.floor(Math.random()*PALETTE.length)],
      trail: [],
      trailLen: 5 + Math.floor(Math.random()*5),
      cOx: (Math.random()<0.5?-1:1)*W()*0.06,
      cOy: (Math.random()<0.5?-1:1)*H()*0.05
    });
  }

  function frame(t){
    petalLayers.forEach(function(l){ drawPetalLayer(l, t); });

    particles.forEach(function(p){
      p.angle += p.speed;
      const wobble = Math.sin(t*p.wobSpeed)*p.wob;
      const r = p.orbitR + wobble;
      const centerX = cx + p.cOx;
      const centerY = cy + p.cOy;
      const x = centerX + Math.cos(p.angle)*r;
      const y = centerY + Math.sin(p.angle)*r*0.78;

      p.trail.push({x:x, y:y});
      if(p.trail.length > p.trailLen) p.trail.shift();

      for(let i=0;i<p.trail.length;i++){
        const pt = p.trail[i];
        const k = i/p.trail.length;
        ctx.beginPath();
        ctx.fillStyle = hexAlpha(p.color, k*0.45);
        ctx.arc(pt.x, pt.y, p.size*k, 0, Math.PI*2);
        ctx.fill();
      }

      ctx.save();
      ctx.shadowBlur = 7;
      ctx.shadowColor = hexAlpha(p.color, 0.7);
      ctx.beginPath();
      ctx.fillStyle = hexAlpha(p.color, 0.9);
      ctx.arc(x, y, p.size, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();
    });

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
